#!/usr/bin/env node
/*
 * android-permissions.js
 *
 * Capacitor's Android WebChromeClient already asks for RECORD_AUDIO at runtime
 * when the web page calls getUserMedia(), but the request is only shown if the
 * app actually declares the microphone permission in its manifest. The android/
 * folder is regenerated by `npx cap add android` on every build, so this script
 * re-adds the declaration after that step.
 *
 * Run it from the repository root, after `npx cap add android` / `npx cap sync`:
 *
 *     node scripts/android-permissions.js
 *
 * It is idempotent and exits with an error if the manifest is missing, so a
 * broken pipeline fails loudly instead of shipping a silent-mic APK.
 */

const fs = require("fs");
const path = require("path");

const manifestPath = path.join("android", "app", "src", "main", "AndroidManifest.xml");

const wanted = [
  '<uses-permission android:name="android.permission.RECORD_AUDIO" />',
  '<uses-permission android:name="android.permission.MODIFY_AUDIO_SETTINGS" />',
  '<uses-feature android:name="android.hardware.microphone" android:required="false" />'
];

if (!fs.existsSync(manifestPath)) {
  console.error("[android-permissions] " + manifestPath + " not found.");
  console.error("[android-permissions] run this after `npx cap add android`.");
  process.exit(1);
}

let xml = fs.readFileSync(manifestPath, "utf8");

// A permission is "present" whether or not the tag is self-closed with a space.
const present = (tag) => xml.indexOf(tag) >= 0 || xml.indexOf(tag.replace(" />", "/>")) >= 0;
const missing = wanted.filter((tag) => !present(tag));

if (missing.length === 0) {
  console.log("[android-permissions] microphone permissions already present, nothing to do.");
  process.exit(0);
}

const open = xml.match(/<manifest\b[^>]*>/);
if (!open) {
  console.error("[android-permissions] could not find the <manifest> tag in " + manifestPath);
  process.exit(1);
}

const block =
  "\n    <!-- Microphone access for the web tuner (added by scripts/android-permissions.js) -->\n" +
  missing.map((tag) => "    " + tag).join("\n") +
  "\n";

const at = open.index + open[0].length;
xml = xml.slice(0, at) + block + xml.slice(at);

fs.writeFileSync(manifestPath, xml);
console.log("[android-permissions] added " + missing.length + " entr" + (missing.length === 1 ? "y" : "ies") + " to " + manifestPath);
